const root = $json.body || $json || {};
const data = root.data || {};

const key = data.key || {};
const message = data.message || {};

const waNumber = String(
  key.remoteJidAlt ||
  key.remoteJid ||
  ""
)
  .replace(/@s\.whatsapp\.net$/, "")
  .replace(/@lid$/, "")
  .replace(/[^0-9]/g, "");

const pushName = String(data.pushName || "").trim();

const messageType = String(
  data.messageType || ""
).trim();

let messageText = "";
let mediaType = null;
let hasMedia = false;

// TEXT
if (message.conversation) {
  messageText = message.conversation;
}

else if (message.extendedTextMessage?.text) {
  messageText = message.extendedTextMessage.text;
}

// IMAGE
else if (message.imageMessage) {
  mediaType = "image";
  hasMedia = true;
  messageText = message.imageMessage.caption || "";
}

// VIDEO
else if (message.videoMessage) {
  mediaType = "video";
  hasMedia = true;
  messageText = message.videoMessage.caption || "";
}

// AUDIO
else if (message.audioMessage) {
  mediaType = "audio";
  hasMedia = true;
}

// DOCUMENT
else if (message.documentMessage) {
  mediaType = "document";
  hasMedia = true;
}

// BUTTON
else if (message.buttonsResponseMessage?.selectedDisplayText) {
  messageText = message.buttonsResponseMessage.selectedDisplayText;
}

// LIST
else if (message.listResponseMessage?.title) {
  messageText = message.listResponseMessage.title;
}

messageText = String(messageText || "").trim();

return {
  json: {
    event: root.event || "",
    instance: root.instance || "",

    waNumber,
    pushName,

    messageType,
    mediaType,
    hasMedia,

    messageText,

    messageId: String(key.id || `MSG-${Date.now()}`),

    fromMe: Boolean(key.fromMe),

    isText: messageType === "conversation" ||
            !!message.conversation ||
            !!message.extendedTextMessage,

    isImage: !!message.imageMessage,

    isAudio: !!message.audioMessage,

    isVideo: !!message.videoMessage,

    isDocument: !!message.documentMessage,

    receivedAt: new Date().toISOString(),

    // Keep the original message so later nodes can access media information
    originalMessage: message,
  }
};

const n = $("Code - Normalize Incoming Payload").item.json;
const id = "STU-" + n.waNumber.slice(-6) + "-" + String(Date.now()).slice(-4);
const now = new Date().toISOString();
return { json: {
  "Student ID": id,
  "Student Name": n.pushName || "New Student",
  "WhatsApp Number": n.waNumber,
  "University": "",
  "Major": "",
  "Academic Level": "",
  "Preferred Language": "English",
  "Preferred Explanation Level": "intermediate",
  "Current Semester": "",
  "Registration Date": now,
  "Last Activity": now,
  "Student Status": "ACTIVE"
} };

const raw = ($json.output && typeof $json.output === "object") ? $json.output : $json;
const valid = ["STUDY_EXPLANATION","QUESTION_SOLVING","SUMMARY","QUIZ","STUDY_PLAN","PROGRESS","COURSE_INFORMATION","GENERAL_INFORMATION","HUMAN_SUPPORT","EMERGENCY","UNKNOWN"];
let intent = String(raw.intent || "UNKNOWN").toUpperCase();
if (!valid.includes(intent)) intent = "UNKNOWN";
let confidence = Number(raw.confidence);
if (isNaN(confidence) || confidence < 0 || confidence > 1) confidence = 0;
let priority = String(raw.priority || "NORMAL").toUpperCase();
if (!["LOW","NORMAL","HIGH"].includes(priority)) priority = "NORMAL";
const isEmergency = raw.is_emergency === true || intent === "EMERGENCY";
const requiresHuman = raw.requires_human === true || intent === "HUMAN_SUPPORT" || isEmergency;
if (confidence > 0 && confidence < 0.35 && !isEmergency) intent = "UNKNOWN";
return { json: {
  intent, confidence, priority,
  is_emergency: isEmergency,
  requires_human: requiresHuman,
  course: String(raw.course || ""),
  topic: String(raw.topic || ""),
} };

const text = $("Code - Assemble Student Context").item.json.messageText || "";
const size = 1500;
const chunks = [];
for (let i = 0; i < text.length; i += size) { chunks.push(text.slice(i, i + size)); }
const sep = String.fromCharCode(10) + "---" + String.fromCharCode(10);
return { json: { summaryInput: chunks.join(sep), chunkCount: chunks.length } };

const msg = $("Code - Assemble Student Context").item.json.messageText || "";
const after = msg.split(/answers\s*:/i)[1] || "";
const given = after.split(/[^A-Da-d]+/).filter(Boolean).map(function(s){ return s.toUpperCase(); });
const keyRaw = $("Code - Assemble Student Context").item.json.answerKey || "";
const key = keyRaw ? keyRaw.split(",") : given.map(function(){ return "A"; });
let correct = 0;
const total = Math.max(given.length, key.length) || 1;
for (let i = 0; i < Math.min(given.length, key.length); i++) { if (given[i] === key[i]) correct++; }
const score = Math.round((correct / total) * 100);
let level = "Needs Work"; if (score >= 80) level = "Strong"; else if (score >= 50) level = "Developing";
return { json: {
  quizId: "QZ-EVAL-" + Date.now(),
  course: $("Code - Validate Classification").item.json.course,
  topic: $("Code - Validate Classification").item.json.topic,
  numberOfQuestions: total,
  correctAnswers: correct,
  score,
  performanceLevel: level,
} };

const LF = String.fromCharCode(10);
const rawText = String($json.text || $json.output || '').trim();

let data = {};

try {
  // Remove Markdown code fences if the model returns ```json ... ```
  const cleaned = rawText
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  data = JSON.parse(cleaned);
} catch (error) {
  // Try to extract the JSON object from surrounding explanation text
  const start = rawText.indexOf('{');
  const end = rawText.lastIndexOf('}');

  if (start >= 0 && end > start) {
    try {
      data = JSON.parse(rawText.slice(start, end + 1));
    } catch (secondError) {
      data = {};
    }
  }
}

const questions = Array.isArray(data.questions)
  ? data.questions.filter((question) =>
      question &&
      typeof question.q === 'string' &&
      Array.isArray(question.options) &&
      question.options.length === 4 &&
      typeof question.answer === 'string'
    )
  : [];

if (questions.length === 0) {
  return {
    json: {
      quizGenerationFailed: true,
      quizMessage: 'I could not generate a valid quiz this time. Please try again with a specific course and topic.'
    }
  };
}

const quizId = `QZ-${Date.now()}`;
const answerKey = questions
  .map((question) => question.answer.trim().charAt(0).toUpperCase())
  .join(',');

let quizMessage = `Quiz ${quizId}`;

questions.forEach((question, index) => {
  quizMessage +=
    LF + LF +
    `${index + 1}) ${question.q}` +
    LF +
    question.options.join(LF);
});

quizMessage +=
  LF + LF +
  `Reply with: Quiz ${quizId} answers: A,B,C,... to get your score.`;

return {
  json: {
    quizGenerationFailed: false,
    quizId,
    course: $('Code - Validate Classification').item.json.course,
    topic: $('Code - Validate Classification').item.json.topic,
    numberOfQuestions: questions.length,
    answerKey,
    quizMessage
  }
};

const msg = ($("Code - Assemble Student Context").item.json.messageText || "").toLowerCase();
const m = msg.match(/(\d+)\s*(day|days|week|weeks)/);
let days = 7;
if (m) { days = parseInt(m[1], 10); if (/week/.test(m[2])) days = days * 7; }
return { json: {
  daysUntilExam: days,
  course: $("Code - Validate Classification").item.json.course,
  topic: $("Code - Validate Classification").item.json.topic,
} };

const rows = Array.isArray($json.progressRows)
  ? $json.progressRows
  : [];

const weakTopics = [];
const strongTopics = [];

for (const row of rows) {
  const score = Number(row["Quiz Score"] || 0);
  const topic = String(row.Topic || "").trim();

  if (!topic) continue;

  if (score < 60) {
    weakTopics.push(`${topic} (${score}%)`);
  } else {
    strongTopics.push(`${topic} (${score}%)`);
  }
}

return {
  json: {
    weakTopics,
    strongTopics,
    progressSummary: `Weak topics: ${weakTopics.join(", ") || "None"}. Strong topics: ${strongTopics.join(", ") || "None"}.`
  }
};
